/**
 * emit to subscription queries of type FindBOMItem,
 * but only if the id matches
 *
 * @param		entity	BOMItem
 */
	protected void emitFindBOMItem( BOMItem entity ) {
		LOGGER.info("handling emitFindBOMItem" );
		
	    queryUpdateEmitter.emit(FindBOMItemQuery.class,
	                            query -> query.getFilter().getBOMItemId().equals(entity.getBOMItemId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllBOMItem
	 * 
	 * @param		entity	BOMItem
	 */
	protected void emitFindAllBOMItem( BOMItem entity ) {
		LOGGER.info("handling emitFindAllBOMItem" );
		
	    queryUpdateEmitter.emit(FindAllBOMItemQuery.class,
	                            query -> true,
	                            entity);
	}

